INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Anwenderprogramme immer für technische Nutzer gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Laien"}, {"text": "Ja", "correct": false, "because": "Breite Zielgruppe"}]'),
